struct Violation { let field: String; let code: String; let message: String }

struct Notification {
    private(set) var errors: [Violation] = []
    mutating func add(_ field: String, _ code: String, _ message: String) {
        errors.append(Violation(field: field, code: code, message: message))
    }
    var hasErrors: Bool { !errors.isEmpty }
}

let note = validate(request)                 // every independent check ran
